mapper.select:
select t.VALUE_SOURCE as valueSource, t.CURVE_GROUP_CODE as curveGroupCode, t.CURVE_GROUP_NAME as curveGroupName, t.REMARK as remark from MST_CURVE_GROUP t
1=1
and t.CURVE_GROUP_CODE = #{curveGroupCode}
and t.CURVE_GROUP_NAME LIKE CONCAT('%', CONCAT(#{curveGroupName}, '%'))
and t.VALUE_SOURCE = #{valueSource}
